insert into questions (id, subject_id, concept_ids, difficulty, type, marks, level, stage, body, status, content_version) values
  ('q_c9_sav_l001', 'cbse_9_maths', array['c9.sav.cuboid_cube'], 1, 'mcq', 1, 1, 'FOUNDATION', $${"stem": "A cuboid-shaped box has length 8 cm, breadth 5 cm and height 3 cm, as shown: the longest edge is length, the shorter base edge is breadth, and the vertical edge is height. Which edge is the breadth?", "options": ["The $5$ cm edge", "The $8$ cm edge", "The $3$ cm edge", "There is no breadth edge"], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "generic.misread_question"}, {"optionIndex": 2, "explanation": "c9.sav.cub.lateral_vs_total"}, {"optionIndex": 3, "explanation": "generic.misread_question"}], "hints": ["Length is the longest base edge, breadth is the shorter base edge, and height is vertical."], "solutionSteps": ["By convention, length $= 8$ cm (longest base edge), breadth $= 5$ cm (shorter base edge), height $= 3$ cm (vertical edge).", "So the breadth is the $5$ cm edge."]}$$::jsonb, 'review', 1),
  ('q_c9_sav_l002', 'cbse_9_maths', array['c9.sav.cuboid_cube'], 1, 'numeric', 1, 2, 'FOUNDATION', $${"stem": "A cuboid has length $l$, breadth $b$ and height $h$. Its total surface area is $2(lb + bh + hl)$. If $l = 1$, $b = 1$ and $h = 1$ (a unit cube), what is its total surface area?", "numericAnswer": "6", "unit": "cm^2", "hints": ["Substitute $l = b = h = 1$ into $2(lb + bh + hl)$.", "$lb + bh + hl = 1 + 1 + 1 = 3$, then double it."], "solutionSteps": ["$2(1 \\times 1 + 1 \\times 1 + 1 \\times 1) = 2(3) = 6$"]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l003', 'cbse_9_maths', array['c9.sav.cuboid_cube'], 1, 'numeric', 1, 3, 'FOUNDATION', $${"stem": "A cuboid has length $8$ cm, breadth $5$ cm and height $3$ cm. Find its total surface area.", "numericAnswer": "158", "unit": "cm^2", "hints": ["Total surface area $= 2(lb + bh + hl)$.", "$lb = 40$, $bh = 15$, $hl = 24$."], "solutionSteps": ["$lb + bh + hl = 8(5) + 5(3) + 3(8) = 40 + 15 + 24 = 79$", "TSA $= 2 \\times 79 = 158\\ \\text{cm}^2$"]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l004', 'cbse_9_maths', array['c9.sav.cuboid_cube'], 1, 'mcq', 1, 4, 'FOUNDATION', $${"stem": "A cuboid has length $8$ cm, breadth $5$ cm and height $3$ cm. What is its total surface area?", "options": ["$158\\text{ cm}^2$", "$79\\text{ cm}^2$", "$120\\text{ cm}^2$", "$79\\text{ cm}^3$"], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "c9.sav.cub.forgets_2"}, {"optionIndex": 2, "explanation": "generic.arithmetic_slip"}, {"optionIndex": 3, "explanation": "c9.sav.units.area_as_volume"}], "hints": ["You already found $lb + bh + hl$ in L3. What does the total surface area formula do with that sum?", "Total surface area $= 2(lb + bh + hl)$. Don't forget the $2$."], "solutionSteps": ["$lb + bh + hl = 40 + 15 + 24 = 79$.", "TSA $= 2 \\times 79 = 158\\ \\text{cm}^2$. Stopping at $79$ only counts each face pair once instead of twice."]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l005', 'cbse_9_maths', array['c9.sav.cuboid_cube'], 1, 'mcq', 1, 5, 'FOUNDATION', $${"stem": "Which statement correctly describes a cube?", "options": ["A cube is a cuboid where $l = b = h$", "A cube is a cuboid with no height", "A cube has $8$ faces", "A cube is only defined by its volume, not its surface area"], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "generic.misread_question"}, {"optionIndex": 2, "explanation": "generic.misread_question"}, {"optionIndex": 3, "explanation": "generic.misread_question"}], "hints": ["Think about what makes a cube special among cuboids: is it a different shape, or a cuboid with equal edges?"], "solutionSteps": ["A cube is simply a cuboid whose length, breadth and height are all equal: $l = b = h$.", "Every cube formula (TSA $= 6a^2$, volume $= a^3$) is the general cuboid formula with $l = b = h = a$ substituted in."]}$$::jsonb, 'review', 1),
  ('q_c9_sav_l006', 'cbse_9_maths', array['c9.sav.cuboid_cube'], 1, 'numeric', 1, 6, 'FOUNDATION', $${"stem": "A cube has side $4$ cm. Find its total surface area.", "numericAnswer": "96", "unit": "cm^2", "hints": ["For a cube, $l = b = h = a$, so TSA $= 2(a^2+a^2+a^2) = 6a^2$."], "solutionSteps": ["TSA $= 6a^2 = 6 \\times 4^2 = 6 \\times 16 = 96\\ \\text{cm}^2$"]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l007', 'cbse_9_maths', array['c9.sav.cuboid_cube'], 1, 'numeric', 1, 7, 'FOUNDATION', $${"stem": "A cuboid has length $8$ cm, breadth $5$ cm and height $3$ cm (the same cuboid as before). Find its volume.", "numericAnswer": "120", "unit": "cm^3", "hints": ["Volume of a cuboid $= l \\times b \\times h$."], "solutionSteps": ["Volume $= 8 \\times 5 \\times 3 = 120\\ \\text{cm}^3$"]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l008', 'cbse_9_maths', array['c9.sav.cuboid_cube'], 2, 'case_based', 2, 8, 'FOUNDATION', $${"stem": "Foundation checkpoint. A cube has side $6$ cm. Answer both parts about it.", "parts": [{"stem": "Find the cube's volume.", "numericAnswer": "216", "unit": "cm^3", "hints": [], "solutionSteps": ["Volume $= a^3 = 6^3 = 216\\ \\text{cm}^3$"], "marks": 1, "type": "numeric", "concept_ids": ["c9.sav.cuboid_cube"]}, {"stem": "Find the cube's total surface area.", "numericAnswer": "216", "unit": "cm^2", "hints": [], "solutionSteps": ["TSA $= 6a^2 = 6 \\times 6^2 = 216\\ \\text{cm}^2$"], "marks": 1, "type": "numeric", "concept_ids": ["c9.sav.cuboid_cube"]}], "hints": [], "solutionSteps": []}$$::jsonb, 'live', 1),
  ('q_c9_sav_l009', 'cbse_9_maths', array['c9.sav.cylinder'], 1, 'mcq', 1, 9, 'GUIDED_PRACTICE', $${"stem": "A right circular cylinder is labelled with $r$ (the radius of its circular base) and $h$ (its vertical height). If a cylinder is $10$ cm tall and its circular base has radius $7$ cm, what is $h$?", "options": ["$10$ cm", "$7$ cm", "$17$ cm", "$70$ cm"], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "generic.misread_question"}, {"optionIndex": 2, "explanation": "generic.arithmetic_slip"}, {"optionIndex": 3, "explanation": "generic.arithmetic_slip"}], "hints": ["$h$ is the height (how tall it stands); $r$ is the base radius (how wide the circle is)."], "solutionSteps": ["The height $h$ is explicitly given as $10$ cm; the radius $r = 7$ cm is a separate measurement."]}$$::jsonb, 'review', 1),
  ('q_c9_sav_l010', 'cbse_9_maths', array['c9.sav.cylinder'], 1, 'numeric', 1, 10, 'GUIDED_PRACTICE', $${"stem": "The curved surface area of a cylinder is $2\\pi r h$. If $r = 1$ and $h = 1$, what is the curved surface area (leave your answer as a multiple of $\\pi$; enter just the coefficient of $\\pi$)?", "numericAnswer": "2", "unit": "none", "hints": ["Substitute $r = 1, h = 1$ into $2\\pi r h$ and read off the coefficient of $\\pi$."], "solutionSteps": ["$2\\pi(1)(1) = 2\\pi$, so the coefficient is $2$."]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l011', 'cbse_9_maths', array['c9.sav.cylinder'], 1, 'numeric', 1, 11, 'GUIDED_PRACTICE', $${"stem": "A cylinder has radius $7$ cm and height $10$ cm. Find its curved surface area. (Use $\\pi = \\frac{22}{7}$.)", "numericAnswer": "440", "unit": "cm^2", "hints": ["Curved surface area $= 2\\pi r h$.", "$\\pi = \\frac{22}{7}$ is chosen to cancel neatly with $r = 7$."], "solutionSteps": ["CSA $= 2 \\times \\frac{22}{7} \\times 7 \\times 10 = 2 \\times 22 \\times 10 = 440\\ \\text{cm}^2$"]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l012', 'cbse_9_maths', array['c9.sav.cylinder'], 2, 'mcq', 1, 12, 'GUIDED_PRACTICE', $${"stem": "A cylinder has radius $7$ cm and height $10$ cm (the same cylinder as before). What is its total surface area? (Use $\\pi = \\frac{22}{7}$.)", "options": ["$748\\text{ cm}^2$", "$440\\text{ cm}^2$", "$1540\\text{ cm}^2$", "$308\\text{ cm}^2$"], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "c9.sav.cyl.curved_for_total"}, {"optionIndex": 2, "explanation": "generic.misread_question"}, {"optionIndex": 3, "explanation": "generic.arithmetic_slip"}], "hints": ["Total surface area adds the two circular ends to the curved surface: $2\\pi r h + 2\\pi r^2 = 2\\pi r(r+h)$."], "solutionSteps": ["TSA $= 2\\pi r(r+h) = 2 \\times \\frac{22}{7} \\times 7 \\times (7+10) = 44 \\times 17 = 748\\ \\text{cm}^2$", "The curved surface area alone (from L11) was only $440\\ \\text{cm}^2$ \u2014 that is not the total."]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l013', 'cbse_9_maths', array['c9.sav.cylinder'], 2, 'numeric', 1, 13, 'GUIDED_PRACTICE', $${"stem": "Find the volume of the same cylinder (radius $7$ cm, height $10$ cm). (Use $\\pi = \\frac{22}{7}$.)", "numericAnswer": "1540", "unit": "cm^3", "hints": ["Volume $= \\pi r^2 h$."], "solutionSteps": ["Volume $= \\frac{22}{7} \\times 7^2 \\times 10 = 22 \\times 7 \\times 10 = 1540\\ \\text{cm}^3$"]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l014', 'cbse_9_maths', array['c9.sav.cone'], 1, 'mcq', 1, 14, 'GUIDED_PRACTICE', $${"stem": "A right circular cone has three key lengths: $r$ (base radius), $h$ (the vertical height from the apex straight down to the base), and $l$ (the slant height, from the apex down the sloping surface to the base). Which one is measured along the cone's sloping outer surface?", "options": ["The slant height $l$", "The radius $r$", "The height $h$", "None of them"], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "generic.misread_question"}, {"optionIndex": 2, "explanation": "c9.sav.cone.height_for_slant"}, {"optionIndex": 3, "explanation": "generic.misread_question"}], "hints": ["Picture running your finger from the tip of the cone down its outside surface to the base edge \u2014 which length is that?"], "solutionSteps": ["The slant height $l$ runs along the cone's outer sloping surface; $h$ is the straight vertical height inside the cone, and $r$ is the base radius."]}$$::jsonb, 'review', 1),
  ('q_c9_sav_l015', 'cbse_9_maths', array['c9.sav.cone'], 2, 'numeric', 1, 15, 'GUIDED_PRACTICE', $${"stem": "A cone has radius $6$ cm and height $8$ cm. Find its slant height.", "numericAnswer": "10", "unit": "cm", "hints": ["The radius, height and slant height form a right triangle: $l^2 = r^2 + h^2$ (this is the Pythagoras rule from Class 8).", "$l = \\sqrt{6^2 + 8^2} = \\sqrt{36+64} = \\sqrt{100}$"], "solutionSteps": ["$l = \\sqrt{r^2+h^2} = \\sqrt{6^2+8^2} = \\sqrt{100} = 10\\ \\text{cm}$"]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l016', 'cbse_9_maths', array['c9.sav.cone'], 2, 'numeric', 1, 16, 'GUIDED_PRACTICE', $${"stem": "Using the cone from before (radius $6$ cm, height $8$ cm, slant height $10$ cm), find its curved surface area. (Use $\\pi = 3.14$.)", "numericAnswer": "188.4", "unit": "cm^2", "hints": ["Curved surface area $= \\pi r l$, using the slant height $l$, not $h$."], "solutionSteps": ["CSA $= \\pi r l = 3.14 \\times 6 \\times 10 = 188.4\\ \\text{cm}^2$"]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l017', 'cbse_9_maths', array['c9.sav.cone'], 2, 'mcq', 1, 17, 'GUIDED_PRACTICE', $${"stem": "A cone has radius $6$ cm and height $8$ cm. What is its curved surface area? (Use $\\pi = 3.14$.)", "options": ["$188.4\\text{ cm}^2$", "$150.72\\text{ cm}^2$", "$301.44\\text{ cm}^3$", "$62.8\\text{ cm}^2$"], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "c9.sav.cone.height_for_slant"}, {"optionIndex": 2, "explanation": "c9.sav.cone.no_third"}, {"optionIndex": 3, "explanation": "generic.arithmetic_slip"}], "hints": ["The formula needs the slant height $l$, not $h$. Have you found $l$ yet?", "$l = \\sqrt{r^2+h^2} = \\sqrt{36+64} = 10$. Now use CSA $= \\pi r l$."], "solutionSteps": ["The slant height is not given directly: $l = \\sqrt{6^2+8^2} = 10$.", "CSA $= \\pi r l = 3.14 \\times 6 \\times 10 = 188.4\\ \\text{cm}^2$."]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l018', 'cbse_9_maths', array['c9.sav.pyramid'], 1, 'mcq', 1, 18, 'GUIDED_PRACTICE', $${"stem": "A pyramid stands on a square base, with four triangular faces meeting at an apex. Each triangular face has its own slant height (from the apex down the middle of that face to the base edge). Which of these is generally NOT the same as the pyramid's own vertical height (measured straight up from the base's centre to the apex)?", "options": ["A triangular face's slant height", "The base's side length", "The base's area", "None \u2014 they're all the same as the vertical height"], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "generic.misread_question"}, {"optionIndex": 2, "explanation": "generic.misread_question"}, {"optionIndex": 3, "explanation": "c9.sav.pyr.vertical_for_slant"}], "hints": ["The vertical height goes straight up from the centre of the base; a face's slant height goes up along the middle of a tilted triangular face. Are these the same line?"], "solutionSteps": ["The vertical height and a face's slant height are different lengths (the slant height is always longer, since it's the hypotenuse of a right triangle formed with half the base and the vertical height).", "Confusing them is the single most common pyramid error in this chapter."]}$$::jsonb, 'review', 1),
  ('q_c9_sav_l019', 'cbse_9_maths', array['c9.sav.pyramid', 'c9.sav.cuboid_cube'], 2, 'case_based', 2, 19, 'GUIDED_PRACTICE', $${"stem": "Guided Practice checkpoint. A pyramid has a square base of side $6$ cm, vertical height $4$ cm, and each triangular face has slant height $5$ cm (measured up the middle of the face).", "parts": [{"stem": "Find the pyramid's volume.", "numericAnswer": "48", "unit": "cm^3", "hints": [], "solutionSteps": ["Volume $= \\frac{1}{3} \\times \\text{base area} \\times \\text{height} = \\frac{1}{3} \\times 6^2 \\times 4 = \\frac{1}{3} \\times 36 \\times 4 = 48\\ \\text{cm}^3$"], "marks": 1, "type": "numeric", "concept_ids": ["c9.sav.pyramid", "c9.sav.cuboid_cube"]}, {"stem": "Find the pyramid's total surface area.", "numericAnswer": "96", "unit": "cm^2", "hints": [], "solutionSteps": ["TSA $=$ base area $+$ (4 triangular faces) $= 6^2 + 4 \\times \\left(\\frac{1}{2} \\times 6 \\times 5\\right) = 36 + 60 = 96\\ \\text{cm}^2$", "Each triangular face uses the slant height $5$ cm, not the pyramid's vertical height $4$ cm."], "marks": 1, "type": "numeric", "concept_ids": ["c9.sav.pyramid", "c9.sav.cuboid_cube"]}], "hints": [], "solutionSteps": []}$$::jsonb, 'live', 1),
  ('q_c9_sav_l020', 'cbse_9_maths', array['c9.sav.sphere_hemisphere'], 1, 'mcq', 1, 20, 'SKILL_BUILDING', $${"stem": "A sphere is a full ball shape. A hemisphere is exactly half of a sphere, cut through its centre. Which of these does a hemisphere have that a full sphere does NOT?", "options": ["A flat circular face where it was cut", "A curved surface", "A radius", "A centre point"], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "generic.misread_question"}, {"optionIndex": 2, "explanation": "generic.misread_question"}, {"optionIndex": 3, "explanation": "generic.misread_question"}], "hints": ["Picture cutting an orange exactly in half through its centre \u2014 what new, flat surface appears that wasn't there before?"], "solutionSteps": ["Cutting a sphere in half creates one new flat circular face at the cut \u2014 the sphere itself has no flat faces anywhere.", "This flat face is why a hemisphere's total surface area needs an extra term beyond just its curved part."]}$$::jsonb, 'review', 1),
  ('q_c9_sav_l021', 'cbse_9_maths', array['c9.sav.sphere_hemisphere'], 1, 'numeric', 1, 21, 'SKILL_BUILDING', $${"stem": "A sphere has radius $21$ cm. Find its surface area. (Use $\\pi = \\frac{22}{7}$.)", "numericAnswer": "5544", "unit": "cm^2", "hints": ["A sphere's surface area is $4\\pi r^2$."], "solutionSteps": ["SA $= 4\\pi r^2 = 4 \\times \\frac{22}{7} \\times 21^2 = 4 \\times \\frac{22}{7} \\times 441 = 5544\\ \\text{cm}^2$"]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l022', 'cbse_9_maths', array['c9.sav.sphere_hemisphere'], 2, 'numeric', 1, 22, 'SKILL_BUILDING', $${"stem": "Find the volume of the same sphere (radius $21$ cm). (Use $\\pi = \\frac{22}{7}$.)", "numericAnswer": "38808", "unit": "cm^3", "hints": ["A sphere's volume is $\\frac{4}{3}\\pi r^3$."], "solutionSteps": ["Volume $= \\frac{4}{3}\\pi r^3 = \\frac{4}{3} \\times \\frac{22}{7} \\times 21^3 = \\frac{4}{3} \\times \\frac{22}{7} \\times 9261 = 38808\\ \\text{cm}^3$"]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l023', 'cbse_9_maths', array['c9.sav.sphere_hemisphere'], 2, 'mcq', 1, 23, 'SKILL_BUILDING', $${"stem": "A hemisphere has radius $21$ cm. Find its total surface area (curved surface plus the flat circular face). (Use $\\pi = \\frac{22}{7}$.)", "options": ["$4158\\text{ cm}^2$", "$2772\\text{ cm}^2$", "$5544\\text{ cm}^2$", "$1386\\text{ cm}^2$"], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "c9.sav.sph.hemisphere_total"}, {"optionIndex": 2, "explanation": "generic.misread_question"}, {"optionIndex": 3, "explanation": "generic.arithmetic_slip"}], "hints": ["Total surface area of a hemisphere $= 2\\pi r^2$ (curved) $+ \\pi r^2$ (flat face) $= 3\\pi r^2$."], "solutionSteps": ["TSA $= 3\\pi r^2 = 3 \\times \\frac{22}{7} \\times 441 = 4158\\ \\text{cm}^2$.", "$2772\\ \\text{cm}^2$ is only the curved part ($2\\pi r^2$) \u2014 it forgets the flat circular face from L20."]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l024', 'cbse_9_maths', array['c9.sav.sphere_hemisphere'], 2, 'mcq', 1, 24, 'SKILL_BUILDING', $${"stem": "Find the volume of a hemisphere with radius $6$ cm. (Use $\\pi = \\frac{22}{7}$.)", "options": ["$\\frac{3168}{7}\\text{ cm}^3$", "$\\frac{528}{7}\\text{ cm}^3$", "$\\frac{1584}{7}\\text{ cm}^3$", "$\\frac{6336}{7}\\text{ cm}^3$"], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "c9.sav.sph.r_squared_volume"}, {"optionIndex": 2, "explanation": "generic.arithmetic_slip"}, {"optionIndex": 3, "explanation": "generic.arithmetic_slip"}], "hints": ["A hemisphere's volume is $\\frac{2}{3}\\pi r^3$ \u2014 note the power is $3$, not $2$."], "solutionSteps": ["Volume $= \\frac{2}{3}\\pi r^3 = \\frac{2}{3} \\times \\frac{22}{7} \\times 6^3 = \\frac{2}{3} \\times \\frac{22}{7} \\times 216 = \\frac{3168}{7}\\ \\text{cm}^3$", "Using $r^2$ instead of $r^3$ gives the much smaller, wrong value $\\frac{528}{7}$."]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l025', 'cbse_9_maths', array['c9.sav.cuboid_cube'], 2, 'numeric', 2, 25, 'SKILL_BUILDING', $${"stem": "A cuboid has length $10$ cm, breadth $6$ cm, and volume $300\\text{ cm}^3$. Find its height.", "numericAnswer": "5", "unit": "cm", "hints": ["Volume $= l \\times b \\times h$. You know the volume, $l$ and $b$ \u2014 rearrange for $h$.", "$h = \\frac{\\text{Volume}}{l \\times b}$"], "solutionSteps": ["$300 = 10 \\times 6 \\times h = 60h$", "$h = \\frac{300}{60} = 5\\ \\text{cm}$"]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l026', 'cbse_9_maths', array['c9.sav.cylinder'], 2, 'numeric', 2, 26, 'SKILL_BUILDING', $${"stem": "A cylinder has volume $1540\\text{ cm}^3$ and radius $7$ cm. Find its height. (Use $\\pi = \\frac{22}{7}$.)", "numericAnswer": "10", "unit": "cm", "hints": ["Volume $= \\pi r^2 h$. Solve for $h$."], "solutionSteps": ["$1540 = \\frac{22}{7} \\times 7^2 \\times h = 154h$", "$h = \\frac{1540}{154} = 10\\ \\text{cm}$"]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l027', 'cbse_9_maths', array['c9.sav.cone'], 2, 'numeric', 2, 27, 'SKILL_BUILDING', $${"stem": "A cone has volume $1232\\text{ cm}^3$ and height $24$ cm. Find its radius. (Use $\\pi = \\frac{22}{7}$.)", "numericAnswer": "7", "unit": "cm", "hints": ["Volume $= \\frac{1}{3}\\pi r^2 h$. Solve for $r^2$ first, then take a square root."], "solutionSteps": ["$1232 = \\frac{1}{3} \\times \\frac{22}{7} \\times r^2 \\times 24$", "$r^2 = \\frac{1232 \\times 3 \\times 7}{22 \\times 24} = 49$, so $r = 7\\ \\text{cm}$"]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l028', 'cbse_9_maths', array['c9.sav.cylinder', 'c9.sav.cone', 'c9.sav.sphere_hemisphere'], 2, 'case_based', 3, 28, 'SKILL_BUILDING', $${"stem": "For each solid below, which formula would you reach for FIRST \u2014 no computation needed yet, just identify the right starting formula.", "parts": [{"stem": "A cylindrical pipe's radius and height are given, and you need the amount of metal sheet to make its curved outer surface. Which formula do you start with?", "options": ["$2\\pi rh$", "$\\pi r^2 h$", "$2\\pi r(r+h)$", "$\\pi r l$"], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "generic.misread_question"}, {"optionIndex": 2, "explanation": "c9.sav.cyl.curved_for_total"}, {"optionIndex": 3, "explanation": "generic.misread_question"}], "hints": [], "solutionSteps": ["\"Curved outer surface\" of a cylinder is $2\\pi rh$, not the total (which would also include the two flat ends)."], "marks": 1, "type": "mcq", "concept_ids": ["c9.sav.cylinder", "c9.sav.cone", "c9.sav.sphere_hemisphere"]}, {"stem": "A cone's radius and slant height are given, and you need the amount of canvas for its outer surface (no base). Which formula do you start with?", "options": ["$\\pi r l$", "$\\frac{1}{3}\\pi r^2 h$", "$\\pi r(r+l)$", "$\\pi r h$"], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "c9.sav.cone.no_third"}, {"optionIndex": 2, "explanation": "generic.misread_question"}, {"optionIndex": 3, "explanation": "c9.sav.cone.height_for_slant"}], "hints": [], "solutionSteps": ["Canvas for the outer (curved) surface of a cone uses the slant height: $\\pi r l$."], "marks": 1, "type": "mcq", "concept_ids": ["c9.sav.cylinder", "c9.sav.cone", "c9.sav.sphere_hemisphere"]}, {"stem": "A sphere's radius is given, and you need how much rubber is needed to coat its outside. Which formula do you start with?", "options": ["$4\\pi r^2$", "$\\frac{4}{3}\\pi r^3$", "$2\\pi r^2$", "$3\\pi r^2$"], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "c9.sav.sph.r_squared_volume"}, {"optionIndex": 2, "explanation": "generic.misread_question"}, {"optionIndex": 3, "explanation": "generic.misread_question"}], "hints": [], "solutionSteps": ["Coating the outside of a sphere is its surface area, $4\\pi r^2$ \u2014 the other options are a sphere's volume or a hemisphere's formulas."], "marks": 1, "type": "mcq", "concept_ids": ["c9.sav.cylinder", "c9.sav.cone", "c9.sav.sphere_hemisphere"]}], "hints": [], "solutionSteps": []}$$::jsonb, 'review', 1),
  ('q_c9_sav_l029', 'cbse_9_maths', array['c9.sav.cuboid_cube', 'c9.sav.cylinder', 'c9.sav.units'], 2, 'mcq', 1, 29, 'SKILL_BUILDING', $${"stem": "A matchbox and a metal pipe are both sitting on a table. Before touching any formula, which pair correctly matches each object to its solid?", "options": ["Matchbox: cuboid. Pipe: cylinder.", "Matchbox: cylinder. Pipe: cuboid.", "Both are cuboids.", "Both are cylinders."], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "generic.misread_question"}, {"optionIndex": 2, "explanation": "c9.sav.combo.wrong_solid_id"}, {"optionIndex": 3, "explanation": "c9.sav.combo.wrong_solid_id"}], "hints": ["A matchbox has flat rectangular faces; a pipe has a circular cross-section running along its length."], "solutionSteps": ["A matchbox is a cuboid (all flat rectangular faces); a pipe is a cylinder (a circular cross-section extended along a length).", "Identifying the solid correctly must happen before any formula is chosen \u2014 this is the skill L55 will test on unfamiliar objects."]}$$::jsonb, 'review', 1),
  ('q_c9_sav_l030', 'cbse_9_maths', array['c9.sav.pyramid'], 2, 'numeric', 2, 30, 'SKILL_BUILDING', $${"stem": "A pyramid has volume $100\\text{ cm}^3$ and base area $25\\text{ cm}^2$. Find its height.", "numericAnswer": "12", "unit": "cm", "hints": ["Volume $= \\frac{1}{3} \\times \\text{base area} \\times \\text{height}$. Solve for height."], "solutionSteps": ["$100 = \\frac{1}{3} \\times 25 \\times h$", "$h = \\frac{100 \\times 3}{25} = 12\\ \\text{cm}$"]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l031', 'cbse_9_maths', array['c9.sav.sphere_hemisphere'], 2, 'numeric', 2, 31, 'SKILL_BUILDING', $${"stem": "A sphere has volume $38808\\text{ cm}^3$. Find its radius. (Use $\\pi = \\frac{22}{7}$.)", "numericAnswer": "21", "unit": "cm", "hints": ["Volume $= \\frac{4}{3}\\pi r^3$. Solve for $r^3$ first, then take a cube root."], "solutionSteps": ["$38808 = \\frac{4}{3} \\times \\frac{22}{7} \\times r^3$", "$r^3 = \\frac{38808 \\times 3 \\times 7}{4 \\times 22} = 9261$, so $r = \\sqrt[3]{9261} = 21\\ \\text{cm}$"]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l032', 'cbse_9_maths', array['c9.sav.cuboid_cube'], 2, 'mcq', 1, 32, 'SKILL_BUILDING', $${"stem": "A student solves: 'A cuboid has $l=6$ cm, $b=4$ cm, $h=3$ cm. TSA $= lb+bh+hl = 6(4)+4(3)+3(6) = 24+12+18 = 54\\text{ cm}^2$.' What did the student get wrong?", "options": ["Forgot to multiply the sum by $2$", "Used the wrong formula entirely", "Made an arithmetic mistake in the sum", "Nothing is wrong"], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "generic.misread_question"}, {"optionIndex": 2, "explanation": "generic.misread_question"}, {"optionIndex": 3, "explanation": "c9.sav.cub.forgets_2"}], "hints": ["Check the sum $24+12+18=54$ first \u2014 is that arithmetic correct?", "TSA $= 2(lb+bh+hl)$, not just $lb+bh+hl$."], "solutionSteps": ["The sum $6(4)+4(3)+3(6)=24+12+18=54$ is correct arithmetic, but the student stopped there.", "The correct TSA is $2 \\times 54 = 108\\ \\text{cm}^2$ \u2014 the factor of $2$ was left out."]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l033', 'cbse_9_maths', array['c9.sav.cone'], 2, 'mcq', 1, 33, 'SKILL_BUILDING', $${"stem": "A student solves: 'A cone has $r=5$ cm, $h=12$ cm. CSA $= \\pi r h = \\pi \\times 5 \\times 12 = 60\\pi\\text{ cm}^2$.' What did the student get wrong?", "options": ["Used $h$ instead of the slant height $l$ in the CSA formula", "Used the wrong value of $\\pi$", "Should have used the volume formula instead", "Nothing is wrong"], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "generic.misread_question"}, {"optionIndex": 2, "explanation": "generic.misread_question"}, {"optionIndex": 3, "explanation": "c9.sav.cone.height_for_slant"}], "hints": ["Check which two lengths the CSA formula for a cone actually uses.", "CSA $= \\pi r l$, where $l$ is the slant height \u2014 not the vertical height $h$."], "solutionSteps": ["The formula was applied to the wrong variable: CSA needs the slant height $l = \\sqrt{r^2+h^2} = \\sqrt{25+144} = 13$ cm here, not $h=12$ cm directly.", "The correct CSA is $\\pi \\times 5 \\times 13 = 65\\pi\\ \\text{cm}^2$."]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l034', 'cbse_9_maths', array['c9.sav.sphere_hemisphere'], 2, 'mcq', 1, 34, 'SKILL_BUILDING', $${"stem": "A student solves: 'A hemisphere has radius $6$ cm. Total surface area $= 2\\pi r^2 = 2 \\times \\pi \\times 36 = 72\\pi\\text{ cm}^2$.' What did the student get wrong?", "options": ["Left out the flat circular face; total surface area needs $3\\pi r^2$", "Used the wrong radius", "Should have cubed the radius instead of squaring it", "Nothing is wrong"], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "generic.misread_question"}, {"optionIndex": 2, "explanation": "generic.misread_question"}, {"optionIndex": 3, "explanation": "generic.misread_question"}], "hints": ["$2\\pi r^2$ is only the curved part of a hemisphere's surface. What is missing?"], "solutionSteps": ["$2\\pi r^2$ is the hemisphere's curved surface only; the flat circular face ($\\pi r^2$) where it was cut from the sphere must be added too.", "The correct total is $3\\pi r^2 = 3 \\times \\pi \\times 36 = 108\\pi\\ \\text{cm}^2$."]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l035', 'cbse_9_maths', array['c9.sav.cuboid_cube', 'c9.sav.cylinder', 'c9.sav.cone', 'c9.sav.pyramid', 'c9.sav.sphere_hemisphere'], 2, 'mcq', 1, 35, 'SKILL_BUILDING', $${"stem": "Which of these is the correct volume formula for a right circular cone (radius $r$, height $h$)?", "options": ["$\\frac{1}{3}\\pi r^2 h$", "$\\pi r^2 h$", "$\\frac{1}{3} \\times \\text{base area} \\times h$ using the pyramid's formula shape but forgetting $r^2$ isn't a general base area here", "$\\frac{4}{3}\\pi r^3$"], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "c9.sav.cone.no_third"}, {"optionIndex": 2, "explanation": "generic.misread_question"}, {"optionIndex": 3, "explanation": "generic.misread_question"}], "hints": ["A cone's volume shares the same $\\frac{1}{3} \\times \\text{base} \\times \\text{height}$ shape as a pyramid, with the circular base area $\\pi r^2$."], "solutionSteps": ["A cone's volume is $\\frac{1}{3}\\pi r^2 h$ \u2014 the pyramid's $\\frac{1}{3} \\times \\text{base area} \\times \\text{height}$ pattern, using a circle's area as the base.", "$\\pi r^2 h$ (no third) is the cylinder's volume; $\\frac{4}{3}\\pi r^3$ is the sphere's."]}$$::jsonb, 'review', 1),
  ('q_c9_sav_l036', 'cbse_9_maths', array['c9.sav.cuboid_cube', 'c9.sav.pyramid'], 3, 'case_based', 3, 36, 'SKILL_BUILDING', $${"stem": "A tent shaped like a square pyramid (base $10$ m $\\times$ $8$ m is not square \u2014 instead use base side $8$ m, height $4$ m) stands inside a cuboid room of length $10$ m, breadth $8$ m and height $4$ m.", "parts": [{"stem": "Find the volume of air in the cuboid room.", "numericAnswer": "320", "unit": "m^3", "hints": [], "solutionSteps": ["Room volume $= 10 \\times 8 \\times 4 = 320\\ \\text{m}^3$"], "marks": 1, "type": "numeric", "concept_ids": ["c9.sav.cuboid_cube", "c9.sav.pyramid"]}, {"stem": "The pyramid tent has a square base of side $8$ m and height $4$ m. Find its volume.", "numericAnswer": "85.33", "tolerance": 0.05, "unit": "m^3", "hints": [], "solutionSteps": ["Base area $= 8^2 = 64\\ \\text{m}^2$.", "Pyramid volume $= \\frac{1}{3} \\times 64 \\times 4 = \\frac{256}{3}\\ \\text{m}^3$"], "marks": 1, "type": "numeric", "concept_ids": ["c9.sav.cuboid_cube", "c9.sav.pyramid"]}, {"stem": "How many times bigger is the room's volume than the pyramid tent's volume (as a ratio, rounded to one decimal place)?", "numericAnswer": "3.75", "unit": "none", "hints": [], "solutionSteps": ["$320 \\div \\frac{256}{3} = 320 \\times \\frac{3}{256} = \\frac{960}{256} = 3.75$"], "marks": 1, "type": "numeric", "concept_ids": ["c9.sav.cuboid_cube", "c9.sav.pyramid"]}], "hints": [], "solutionSteps": []}$$::jsonb, 'live', 1),
  ('q_c9_sav_l037', 'cbse_9_maths', array['c9.sav.cylinder', 'c9.sav.cone'], 3, 'numeric', 2, 37, 'SKILL_BUILDING', $${"stem": "A solid is made of a cone (radius $7$ cm, height $6$ cm) sitting on top of a cylinder (the same radius $7$ cm, height $10$ cm). Find the total volume of the solid. (Use $\\pi = \\frac{22}{7}$.)", "numericAnswer": "1848", "unit": "cm^3", "hints": ["The total volume is simply the cylinder's volume plus the cone's volume \u2014 they don't overlap."], "solutionSteps": ["Cylinder volume $= \\frac{22}{7} \\times 7^2 \\times 10 = 1540\\ \\text{cm}^3$", "Cone volume $= \\frac{1}{3} \\times \\frac{22}{7} \\times 7^2 \\times 6 = 308\\ \\text{cm}^3$", "Total $= 1540 + 308 = 1848\\ \\text{cm}^3$"]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l038', 'cbse_9_maths', array['c9.sav.sphere_hemisphere'], 3, 'mcq', 1, 38, 'SKILL_BUILDING', $${"stem": "Skill checkpoint. Assertion (A): A hemisphere's volume is exactly half of a full sphere's volume with the same radius. Reason (R): The hemisphere's volume formula is $\\frac{2}{3}\\pi r^3$, and the sphere's is $\\frac{4}{3}\\pi r^3$, and $\\frac{2}{3}$ is exactly half of $\\frac{4}{3}$. Which is correct?", "options": ["Both A and R are true, and R correctly explains A.", "Both A and R are true, but R does not explain A.", "A is true, but R is false.", "A is false, but R is true."], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "generic.misread_question"}, {"optionIndex": 2, "explanation": "generic.misread_question"}, {"optionIndex": 3, "explanation": "generic.misread_question"}], "hints": ["Check the arithmetic: is $\\frac{2}{3}$ exactly half of $\\frac{4}{3}$?"], "solutionSteps": ["$\\frac{1}{2} \\times \\frac{4}{3} = \\frac{2}{3}$ \u2014 yes, exactly. Both statements are true, and R is precisely why A holds."]}$$::jsonb, 'review', 1),
  ('q_c9_sav_l039', 'cbse_9_maths', array['c9.sav.units'], 1, 'mcq', 1, 39, 'APPLICATION', $${"stem": "$1$ litre equals how many cubic centimetres?", "options": ["$1000\\text{ cm}^3$", "$100\\text{ cm}^3$", "$10\\text{ cm}^3$", "$1\\text{ cm}^3$"], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "generic.arithmetic_slip"}, {"optionIndex": 2, "explanation": "generic.arithmetic_slip"}, {"optionIndex": 3, "explanation": "generic.misread_question"}], "hints": ["A litre is defined as the volume of a $10\\text{ cm} \\times 10\\text{ cm} \\times 10\\text{ cm}$ cube."], "solutionSteps": ["$1\\ \\text{L} = 1000\\ \\text{cm}^3$, since a $10\\times10\\times10$ cm cube has volume $1000\\ \\text{cm}^3$ and holds exactly $1$ litre."]}$$::jsonb, 'review', 1),
  ('q_c9_sav_l040', 'cbse_9_maths', array['c9.sav.units'], 2, 'mcq', 1, 40, 'APPLICATION', $${"stem": "Convert a volume of $2\\text{ m}^3$ into $\\text{cm}^3$.", "options": ["$2{,}000{,}000\\text{ cm}^3$", "$200\\text{ cm}^3$", "$20{,}000\\text{ cm}^3$", "$2{,}000\\text{ cm}^3$"], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "c9.sav.units.m3_cm3"}, {"optionIndex": 2, "explanation": "generic.arithmetic_slip"}, {"optionIndex": 3, "explanation": "generic.arithmetic_slip"}], "hints": ["$1\\text{ m} = 100\\text{ cm}$, so $1\\text{ m}^3 = 100^3\\text{ cm}^3$, not $100\\text{ cm}^3$."], "solutionSteps": ["$1\\text{ m}^3 = 100\\text{ cm} \\times 100\\text{ cm} \\times 100\\text{ cm} = 1{,}000{,}000\\text{ cm}^3$", "$2\\text{ m}^3 = 2 \\times 1{,}000{,}000 = 2{,}000{,}000\\text{ cm}^3$"]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l041', 'cbse_9_maths', array['c9.sav.cuboid_cube', 'c9.sav.units'], 2, 'numeric', 2, 41, 'APPLICATION', $${"stem": "A cuboidal water tank is $2$ m long, $1.5$ m wide and $1$ m deep. Find its capacity in litres.", "numericAnswer": "3000", "unit": "L", "hints": ["First find the volume in $\\text{m}^3$, then convert to litres using $1\\text{ m}^3 = 1000\\text{ L}$."], "solutionSteps": ["Volume $= 2 \\times 1.5 \\times 1 = 3\\ \\text{m}^3$", "Capacity $= 3 \\times 1000 = 3000\\ \\text{L}$"]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l042', 'cbse_9_maths', array['c9.sav.scaling'], 1, 'mcq', 1, 42, 'APPLICATION', $${"stem": "A cube's side length is doubled. Which statement is correct about its new volume, compared to the original?", "options": ["The new volume is $8$ times the original", "The new volume is $2$ times the original", "The new volume is $4$ times the original", "The new volume stays the same"], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "c9.sav.scale.linear"}, {"optionIndex": 2, "explanation": "generic.misread_question"}, {"optionIndex": 3, "explanation": "generic.misread_question"}], "hints": ["Volume depends on the CUBE of the side length, not the side length itself."], "solutionSteps": ["If the side doubles from $a$ to $2a$, the new volume is $(2a)^3 = 8a^3$ \u2014 exactly $8$ times the original $a^3$, not $2$ times.", "This is deliberately asked before the general scaling rule is taught, to surface the doubling-doubles-volume misconception first."]}$$::jsonb, 'review', 1),
  ('q_c9_sav_l043', 'cbse_9_maths', array['c9.sav.scaling'], 2, 'case_based', 2, 43, 'APPLICATION', $${"stem": "If every linear dimension of a solid is scaled by a factor $k$, its surface area and volume scale by predictable powers of $k$.", "parts": [{"stem": "Surface area scales by $k$ raised to what power?", "numericAnswer": "2", "unit": "none", "hints": [], "solutionSteps": ["Surface area is built from products of two lengths (e.g. $l \\times b$), so it scales by $k^2$."], "marks": 1, "type": "numeric", "concept_ids": ["c9.sav.scaling"]}, {"stem": "Volume scales by $k$ raised to what power?", "numericAnswer": "3", "unit": "none", "hints": [], "solutionSteps": ["Volume is built from products of three lengths (e.g. $l \\times b \\times h$), so it scales by $k^3$."], "marks": 1, "type": "numeric", "concept_ids": ["c9.sav.scaling"]}], "hints": [], "solutionSteps": []}$$::jsonb, 'live', 1),
  ('q_c9_sav_l044', 'cbse_9_maths', array['c9.sav.scaling', 'c9.sav.cuboid_cube'], 2, 'numeric', 1, 44, 'APPLICATION', $${"stem": "A cube's side is doubled. What is the ratio of its new volume to its old volume?", "numericAnswer": "8", "unit": "none", "hints": ["Use the rule from L43: volume scales by $k^3$, and here $k=2$."], "solutionSteps": ["Ratio $= k^3 = 2^3 = 8$"]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l045', 'cbse_9_maths', array['c9.sav.scaling', 'c9.sav.sphere_hemisphere'], 2, 'mcq', 1, 45, 'APPLICATION', $${"stem": "A sphere's radius is tripled. What is the ratio of its new surface area to its old surface area?", "options": ["$9$", "$3$", "$27$", "$6$"], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "c9.sav.scale.linear"}, {"optionIndex": 2, "explanation": "generic.arithmetic_slip"}, {"optionIndex": 3, "explanation": "generic.arithmetic_slip"}], "hints": ["Surface area scales by $k^2$ where $k=3$ \u2014 not by $k$ itself."], "solutionSteps": ["Ratio $= k^2 = 3^2 = 9$. (If the question had asked about volume instead, the ratio would be $k^3 = 27$.)"]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l046', 'cbse_9_maths', array['c9.sav.cylinder'], 2, 'numeric', 2, 46, 'APPLICATION', $${"stem": "A cylindrical pillar has radius $1.4$ m and height $5$ m. Find the cost of painting its curved surface at $\\text{\u20b9}20$ per $\\text{m}^2$. (Use $\\pi = \\frac{22}{7}$.)", "numericAnswer": "880", "unit": "none", "hints": ["Only the curved surface is painted (not the flat circular ends), so use $2\\pi rh$.", "Find the area first, then multiply by the rate."], "solutionSteps": ["CSA $= 2\\pi rh = 2 \\times \\frac{22}{7} \\times 1.4 \\times 5 = 44\\ \\text{m}^2$", "Cost $= 44 \\times 20 = \\text{\u20b9}880$"]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l047', 'cbse_9_maths', array['c9.sav.cone'], 2, 'numeric', 2, 47, 'APPLICATION', $${"stem": "A conical tent has radius $7$ m and height $24$ m. Find the cost of the canvas needed at $\\text{\u20b9}100$ per $\\text{m}^2$. (Use $\\pi = \\frac{22}{7}$.)", "numericAnswer": "55000", "unit": "none", "hints": ["You need the slant height first: $l = \\sqrt{r^2+h^2}$.", "Canvas covers only the curved surface: $\\pi r l$."], "solutionSteps": ["$l = \\sqrt{7^2+24^2} = \\sqrt{625} = 25\\ \\text{m}$", "CSA $= \\pi r l = \\frac{22}{7} \\times 7 \\times 25 = 550\\ \\text{m}^2$", "Cost $= 550 \\times 100 = \\text{\u20b9}55000$"]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l048', 'cbse_9_maths', array['c9.sav.cuboid_cube', 'c9.sav.sphere_hemisphere'], 3, 'numeric', 3, 48, 'APPLICATION', $${"stem": "A metal cuboid of dimensions $66\\text{ cm} \\times 28\\text{ cm} \\times 21\\text{ cm}$ is melted and recast into small spheres, each of radius $3.5$ cm. How many spheres are formed? (Use $\\pi = \\frac{22}{7}$.)", "numericAnswer": "216", "unit": "none", "hints": ["Melting and recasting conserves volume: find the cuboid's volume, and one sphere's volume, then divide."], "solutionSteps": ["Cuboid volume $= 66 \\times 28 \\times 21 = 38808\\ \\text{cm}^3$", "One sphere's volume $= \\frac{4}{3} \\times \\frac{22}{7} \\times 3.5^3 = \\frac{539}{3}\\ \\text{cm}^3$", "Number of spheres $= 38808 \\div \\frac{539}{3} = 216$"]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l049', 'cbse_9_maths', array['c9.sav.cylinder', 'c9.sav.sphere_hemisphere'], 3, 'numeric', 2, 49, 'APPLICATION', $${"stem": "A capsule is shaped like a cylinder of radius $3.5$ cm and height $8$ cm, with a hemisphere of the same radius attached at each end. Find its total volume. (Use $\\pi = \\frac{22}{7}$.)", "numericAnswer": "487.67", "tolerance": 0.1, "unit": "cm^3", "hints": ["Total volume $=$ cylinder's volume $+$ (two hemispheres $=$ one full sphere)."], "solutionSteps": ["Cylinder volume $= \\frac{22}{7} \\times 3.5^2 \\times 8 = 308\\ \\text{cm}^3$", "Two hemispheres together $=$ one sphere of radius $3.5$: $\\frac{4}{3} \\times \\frac{22}{7} \\times 3.5^3 = \\frac{539}{3} \\approx 179.67\\ \\text{cm}^3$", "Total $\\approx 308 + 179.67 = 487.67\\ \\text{cm}^3$"]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l050', 'cbse_9_maths', array['c9.sav.cylinder', 'c9.sav.sphere_hemisphere', 'c9.sav.units'], 3, 'mcq', 1, 50, 'APPLICATION', $${"stem": "The same capsule (cylinder radius $3.5$ cm, height $8$ cm, with a hemisphere of the same radius at each end). Find its total surface area. (Use $\\pi = \\frac{22}{7}$.)", "options": ["$330\\text{ cm}^2$", "$407\\text{ cm}^2$", "$176\\text{ cm}^2$", "$154\\text{ cm}^2$"], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "c9.sav.combo.double_counts_shared_face"}, {"optionIndex": 2, "explanation": "generic.misread_question"}, {"optionIndex": 3, "explanation": "generic.misread_question"}], "hints": ["The cylinder's flat circular ends are exactly where the hemispheres attach \u2014 they are internal joins, not part of the outer surface.", "Total surface $=$ cylinder's curved surface $+$ both hemispheres' curved surfaces (no flat faces anywhere, since each join is covered)."], "solutionSteps": ["Cylinder's curved surface $= 2\\pi rh = 2 \\times \\frac{22}{7} \\times 3.5 \\times 8 = 176\\ \\text{cm}^2$", "Both hemispheres' curved surfaces together $=$ one full sphere's surface $= 4\\pi r^2 = 4 \\times \\frac{22}{7} \\times 3.5^2 = 154\\ \\text{cm}^2$", "Total $= 176 + 154 = 330\\ \\text{cm}^2$. Adding the flat circular faces on top of this (getting $407$) double-counts the internal join."]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l051', 'cbse_9_maths', array['c9.sav.cylinder', 'c9.sav.cone'], 3, 'case_based', 4, 51, 'APPLICATION', $${"stem": "A tent is in the shape of a cylinder of radius $7$ m and height $3$ m, surmounted by a cone of the same radius and height $4$ m. (Use $\\pi = \\frac{22}{7}$.)", "parts": [{"stem": "Find the area of canvas needed for the tent (curved surfaces only; the base is not covered).", "numericAnswer": "309.37", "tolerance": 0.1, "unit": "m^2", "hints": [], "solutionSteps": ["Cone's slant height $l = \\sqrt{7^2+4^2} = \\sqrt{65} \\approx 8.06\\ \\text{m}$", "Cylinder's curved surface $= 2\\pi rh = 2 \\times \\frac{22}{7} \\times 7 \\times 3 = 132\\ \\text{m}^2$", "Cone's curved surface $= \\pi r l = 22\\sqrt{65} \\approx 177.37\\ \\text{m}^2$", "Total canvas $\\approx 132 + 177.37 = 309.37\\ \\text{m}^2$"], "marks": 2, "type": "numeric", "concept_ids": ["c9.sav.cylinder", "c9.sav.cone"]}, {"stem": "Find the volume of air inside the tent.", "numericAnswer": "667.33", "tolerance": 0.1, "unit": "m^3", "hints": [], "solutionSteps": ["Cylinder's volume $= \\frac{22}{7} \\times 7^2 \\times 3 = 462\\ \\text{m}^3$", "Cone's volume $= \\frac{1}{3} \\times \\frac{22}{7} \\times 7^2 \\times 4 = \\frac{616}{3} \\approx 205.33\\ \\text{m}^3$", "Total $\\approx 462 + 205.33 = 667.33\\ \\text{m}^3$"], "marks": 2, "type": "numeric", "concept_ids": ["c9.sav.cylinder", "c9.sav.cone"]}], "hints": [], "solutionSteps": []}$$::jsonb, 'live', 1),
  ('q_c9_sav_l052', 'cbse_9_maths', array['c9.sav.units', 'c9.sav.cylinder'], 2, 'numeric', 2, 52, 'APPLICATION', $${"stem": "A rectangular tank of dimensions $3\\text{ m} \\times 2\\text{ m} \\times 1.5\\text{ m}$ is filled from a cylindrical pipe of radius $7$ cm, through which water flows at $6\\text{ m/s}$. How many seconds does it take to fill the tank? (Use $\\pi = \\frac{22}{7}$; work entirely in cm.)", "numericAnswer": "97.4", "tolerance": 0.1, "unit": "s", "hints": ["Convert the tank's volume to $\\text{cm}^3$, and the flow speed to $\\text{cm/s}$, so both sides use the same units.", "The pipe delivers water at a rate of (cross-section area) $\\times$ (speed) $\\text{cm}^3$ per second."], "solutionSteps": ["Tank volume $= 300 \\times 200 \\times 150 = 9{,}000{,}000\\ \\text{cm}^3$", "Pipe's flow rate $= \\pi r^2 \\times \\text{speed} = \\frac{22}{7} \\times 7^2 \\times 600 = 92{,}400\\ \\text{cm}^3/\\text{s}$", "Time $= \\frac{9{,}000{,}000}{92{,}400} \\approx 97.4\\ \\text{s}$"]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l053', 'cbse_9_maths', array['c9.sav.pyramid', 'c9.sav.units'], 3, 'numeric', 3, 53, 'APPLICATION', $${"stem": "A heap of sand is shaped like a pyramid with a square base of area $45\\text{ m}^2$ and height $8$ m. If each truck can carry $12\\text{ m}^3$ of sand, how many truck-loads are needed to move the whole heap?", "numericAnswer": "10", "unit": "none", "hints": ["First find the heap's volume, then divide by one truck's capacity."], "solutionSteps": ["Heap volume $= \\frac{1}{3} \\times 45 \\times 8 = 120\\ \\text{m}^3$", "Truck-loads $= \\frac{120}{12} = 10$"]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l054', 'cbse_9_maths', array['c9.sav.cylinder', 'c9.sav.units', 'c9.sav.scaling'], 3, 'case_based', 4, 54, 'APPLICATION', $${"stem": "Application checkpoint. A cylindrical water tank has radius $7$ m and height $10$ m. (Use $\\pi = \\frac{22}{7}$.)", "parts": [{"stem": "Find the tank's capacity in cubic metres.", "numericAnswer": "1540", "unit": "m^3", "hints": [], "solutionSteps": ["Volume $= \\frac{22}{7} \\times 7^2 \\times 10 = 1540\\ \\text{m}^3$"], "marks": 1, "type": "numeric", "concept_ids": ["c9.sav.cylinder", "c9.sav.units", "c9.sav.scaling"]}, {"stem": "Find the tank's capacity in litres.", "numericAnswer": "1540000", "unit": "L", "hints": [], "solutionSteps": ["$1\\ \\text{m}^3 = 1000\\ \\text{L}$, so $1540\\ \\text{m}^3 = 1{,}540{,}000\\ \\text{L}$"], "marks": 2, "type": "numeric", "concept_ids": ["c9.sav.cylinder", "c9.sav.units", "c9.sav.scaling"]}, {"stem": "If a new tank is built with both the radius and height doubled, what is the ratio of the new tank's volume to the original tank's volume?", "numericAnswer": "8", "unit": "none", "hints": [], "solutionSteps": ["Both dimensions scale by $k=2$, so volume scales by $k^3=8$."], "marks": 1, "type": "numeric", "concept_ids": ["c9.sav.cylinder", "c9.sav.units", "c9.sav.scaling"]}], "hints": [], "solutionSteps": []}$$::jsonb, 'live', 1),
  ('q_c9_sav_l055', 'cbse_9_maths', array['c9.sav.cylinder', 'c9.sav.cone', 'c9.sav.units'], 3, 'mcq', 1, 55, 'MASTERY', $${"stem": "A grain silo is described as follows: a tall cylindrical body with a cone-shaped roof of the same radius on top. No figure is given. Before any numbers, which formulas will you need to find its total volume?", "options": ["A cylinder's volume formula, plus a cone's volume formula, added together", "Only a cylinder's volume formula", "Only a cone's volume formula", "A sphere's volume formula, since a silo is round"], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "c9.sav.combo.wrong_solid_id"}, {"optionIndex": 2, "explanation": "c9.sav.combo.wrong_solid_id"}, {"optionIndex": 3, "explanation": "c9.sav.combo.wrong_solid_id"}], "hints": ["Break the described object into the two solids it's actually built from before reaching for any formula."], "solutionSteps": ["A silo like this decomposes into a cylinder (the tall body) and a cone (the roof) sharing the same radius \u2014 its total volume is the sum of both solids' volumes.", "This decomposition step, done correctly before any computation, is exactly what L56 will now compute."]}$$::jsonb, 'review', 1),
  ('q_c9_sav_l056', 'cbse_9_maths', array['c9.sav.cone', 'c9.sav.cylinder'], 3, 'case_based', 3, 56, 'MASTERY', $${"stem": "The silo from before has radius $7$ m; its cylindrical body is $15$ m tall, and its conical roof is $24$ m tall. (Use $\\pi = \\frac{22}{7}$.)", "parts": [{"stem": "Find the silo's total surface area (the cylinder's curved surface, the cone's curved surface, and the flat circular base \u2014 the top where the cone meets the cylinder is internal and not counted).", "numericAnswer": "1210", "unit": "m^2", "hints": [], "solutionSteps": ["Cone's slant height $l = \\sqrt{7^2+24^2} = \\sqrt{625} = 25\\ \\text{m}$", "Cylinder's curved surface $= 2\\pi rh = 2 \\times \\frac{22}{7} \\times 7 \\times 15 = 660\\ \\text{m}^2$", "Cone's curved surface $= \\pi r l = \\frac{22}{7} \\times 7 \\times 25 = 550\\ \\text{m}^2$", "Total $= 660 + 550 = 1210\\ \\text{m}^2$ (the base is buried/not painted in this scenario, so it is excluded)."], "marks": 2, "type": "numeric", "concept_ids": ["c9.sav.cone", "c9.sav.cylinder"]}, {"stem": "Find the silo's total volume.", "numericAnswer": "3542", "unit": "m^3", "hints": [], "solutionSteps": ["Cylinder's volume $= \\frac{22}{7} \\times 7^2 \\times 15 = 2310\\ \\text{m}^3$", "Cone's volume $= \\frac{1}{3} \\times \\frac{22}{7} \\times 7^2 \\times 24 = 1232\\ \\text{m}^3$", "Total $= 2310 + 1232 = 3542\\ \\text{m}^3$"], "marks": 1, "type": "numeric", "concept_ids": ["c9.sav.cone", "c9.sav.cylinder"]}], "hints": [], "solutionSteps": []}$$::jsonb, 'live', 1),
  ('q_c9_sav_l057', 'cbse_9_maths', array['c9.sav.sphere_hemisphere', 'c9.sav.units'], 3, 'numeric', 3, 57, 'MASTERY', $${"stem": "A hemispherical bowl has a rim of diameter $14$ cm. Find its capacity in litres. (Use $\\pi = \\frac{22}{7}$; give your answer in terms of $\\pi$ is not needed \u2014 use $\\pi=\\frac{22}{7}$ throughout, and give the answer rounded to 3 decimal places.)", "numericAnswer": "0.719", "tolerance": 0.001, "unit": "L", "hints": ["The rim's diameter, not radius, is given \u2014 halve it first.", "A bowl is a hemisphere: volume $= \\frac{2}{3}\\pi r^3$, then convert $\\text{cm}^3$ to litres."], "solutionSteps": ["Radius $= \\frac{14}{2} = 7\\ \\text{cm}$", "Volume $= \\frac{2}{3} \\times \\frac{22}{7} \\times 7^3 = \\frac{2156}{3} \\approx 718.67\\ \\text{cm}^3$", "Capacity $= \\frac{718.67}{1000} \\approx 0.719\\ \\text{L}$"]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l058', 'cbse_9_maths', array['c9.sav.scaling', 'c9.sav.sphere_hemisphere', 'c9.sav.cuboid_cube'], 3, 'mcq', 1, 58, 'MASTERY', $${"stem": "A sphere and a cube have the same volume. If the cube's side is doubled (so its volume becomes $8$ times as large), by what factor must the sphere's radius change so the two solids' volumes stay equal?", "options": ["$2$", "$8$", "$4$", "$\\sqrt{2}$"], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "generic.misread_question"}, {"optionIndex": 2, "explanation": "generic.misread_question"}, {"optionIndex": 3, "explanation": "generic.misread_question"}], "hints": ["Both a cube's and a sphere's volume scale by (linear scale factor)$^3$. If the volume must scale by $8$, what linear factor cubes to give $8$?"], "solutionSteps": ["Both volumes are cubic in their linear dimension, so if the new volume is $8$ times the old, the sphere's radius must scale by $\\sqrt[3]{8} = 2$ \u2014 the same factor as the cube's side.", "This is the same cube-root relationship used in reverse in L31, now applied to compare two different solids."]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l059', 'cbse_9_maths', array['c9.sav.cylinder', 'c9.sav.sphere_hemisphere', 'c9.sav.units'], 3, 'mcq', 1, 59, 'MASTERY', $${"stem": "A capsule is a cylinder of radius $3$ cm and height $10$ cm with a hemisphere attached at each end. A student computes its total surface area as: $2\\pi rh + 2(2\\pi r^2) = 2\\pi(3)(10) + 2(2\\pi(3)^2) = 60\\pi + 36\\pi = 96\\pi\\text{ cm}^2$. Is this correct?", "options": ["Yes, this is correct.", "No \u2014 the cylinder's flat circular ends should have been included too.", "No \u2014 a flat face should have been included for each hemisphere.", "No \u2014 the volume formula was used instead of the surface-area formula."], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "c9.sav.combo.double_counts_shared_face"}, {"optionIndex": 2, "explanation": "c9.sav.combo.double_counts_shared_face"}, {"optionIndex": 3, "explanation": "generic.misread_question"}], "hints": ["Think about what happens at the join between the cylinder and each hemisphere: is there a face there, or not?", "None of the flat faces exist here \u2014 check each term against what the capsule's actual shape needs before assuming an error exists."], "solutionSteps": ["This is the mission's one deliberately CORRECT 'spot the error' problem: the cylinder's flat ends are exactly where the hemispheres attach, so they are internal and rightly excluded.", "Each hemisphere contributes only its curved area ($2\\pi r^2$), with no flat face of its own, since that face is exactly where it joins the cylinder.", "The given computation, $96\\pi\\ \\text{cm}^2$, is correct \u2014 this tests whether the learner has truly internalised the shared-face rule rather than assuming every composite-solid question must contain an error."]}$$::jsonb, 'live', 1),
  ('q_c9_sav_l060', 'cbse_9_maths', array['c9.sav.cylinder', 'c9.sav.cuboid_cube'], 3, 'case_based', 4, 60, 'MASTERY', $${"stem": "A company is deciding between two containers of equal volume ($2200\\text{ cm}^3$) for packaging: a cylindrical can of radius $7$ cm, or a cube. (Use $\\pi = \\frac{22}{7}$.)", "parts": [{"stem": "Find the height of the cylindrical can (rounded to 2 decimal places).", "numericAnswer": "14.29", "tolerance": 0.01, "unit": "cm", "hints": [], "solutionSteps": ["$2200 = \\frac{22}{7} \\times 7^2 \\times h = 154h$", "$h = \\frac{2200}{154} \\approx 14.29\\ \\text{cm}$"], "marks": 2, "type": "numeric", "concept_ids": ["c9.sav.cylinder", "c9.sav.cuboid_cube"]}, {"stem": "For the same volume, which container generally uses LESS material (has smaller total surface area) \u2014 a cylinder, or a cube?", "options": ["It depends on the exact proportions, but a shape closer to a sphere (which a squat, wide cylinder approaches) is usually more efficient than a cube.", "A cube always uses less material than any cylinder of equal volume.", "A cylinder always uses less material than any cube of equal volume.", "Surface area only depends on volume, so both always use exactly the same material."], "correctIndex": 0, "distractors": [{"optionIndex": 1, "explanation": "generic.misread_question"}, {"optionIndex": 2, "explanation": "generic.misread_question"}, {"optionIndex": 3, "explanation": "generic.misread_question"}], "hints": [], "solutionSteps": ["For a fixed volume, a sphere has the least possible surface area of any shape; a cylinder can get closer to that efficiency than a cube can, but only for the right proportions (not any arbitrary tall or flat cylinder).", "This is a reasoning question, not a plug-in-the-formula one \u2014 comparing surface area for equal volume is exactly the kind of judgement real packaging design requires."], "marks": 2, "type": "mcq", "concept_ids": ["c9.sav.cylinder", "c9.sav.cuboid_cube"]}], "hints": [], "solutionSteps": []}$$::jsonb, 'review', 1),
  ('q_c9_sav_l061', 'cbse_9_maths', array['c9.sav.cylinder', 'c9.sav.sphere_hemisphere', 'c9.sav.units'], 3, 'case_based', 5, 61, 'MASTERY', $${"stem": "A water tank is shaped like a cylinder of radius $7$ m and height $10$ m, with a hemispherical dome of the same radius on top (used only as a roof, not filled with water). (Use $\\pi = \\frac{22}{7}$ for area; leave volume answers exact, in terms of $\\pi$ where needed.)", "parts": [{"stem": "Find the volume of water the cylindrical part alone can hold, in litres.", "numericAnswer": "1540000", "unit": "L", "hints": [], "solutionSteps": ["Cylinder volume $= \\frac{22}{7} \\times 7^2 \\times 10 = 1540\\ \\text{m}^3 = 1{,}540{,}000\\ \\text{L}$"], "marks": 1, "type": "numeric", "concept_ids": ["c9.sav.cylinder", "c9.sav.sphere_hemisphere", "c9.sav.units"]}, {"stem": "Find the total outer curved surface area to be painted: the cylinder's curved surface plus the dome's curved surface (the flat top where the dome sits is internal, and the base is on the ground, so neither is painted).", "numericAnswer": "748", "unit": "m^2", "hints": [], "solutionSteps": ["Cylinder's curved surface $= 2\\pi rh = 2 \\times \\frac{22}{7} \\times 7 \\times 10 = 440\\ \\text{m}^2$", "Dome's curved surface (a hemisphere) $= 2\\pi r^2 = 2 \\times \\frac{22}{7} \\times 49 = 308\\ \\text{m}^2$", "Total $= 440 + 308 = 748\\ \\text{m}^2$"], "marks": 2, "type": "numeric", "concept_ids": ["c9.sav.cylinder", "c9.sav.sphere_hemisphere", "c9.sav.units"]}, {"stem": "If the tank (cylinder plus dome) must hold a total of $\\frac{2450}{3}\\pi\\ \\text{m}^3$ of enclosed space (water plus the dome's air), and the radius stays $7$ m, what must the cylinder's height be?", "numericAnswer": "12", "unit": "m", "hints": [], "solutionSteps": ["Dome's volume $= \\frac{2}{3}\\pi r^3 = \\frac{2}{3}\\pi(343) = \\frac{686}{3}\\pi\\ \\text{m}^3$", "Cylinder's volume needed $= \\frac{2450}{3}\\pi - \\frac{686}{3}\\pi = \\frac{1764}{3}\\pi = 588\\pi\\ \\text{m}^3$", "$588\\pi = \\pi(7)^2 h = 49\\pi h$, so $h = \\frac{588}{49} = 12\\ \\text{m}$"], "marks": 2, "type": "numeric", "concept_ids": ["c9.sav.cylinder", "c9.sav.sphere_hemisphere", "c9.sav.units"]}], "hints": [], "solutionSteps": []}$$::jsonb, 'live', 1),
  ('q_c9_sav_l062', 'cbse_9_maths', array['c9.sav.cylinder', 'c9.sav.cone', 'c9.sav.cuboid_cube', 'c9.sav.pyramid', 'c9.sav.sphere_hemisphere', 'c9.sav.scaling', 'c9.sav.units'], 3, 'case_based', 4, 62, 'MASTERY', $${"stem": "Mastery checkpoint / gateway into the Final Mastery Test. A grain silo is described as a cylindrical body of radius $10$ m and height $15$ m, topped with a conical roof of the same radius and height $24$ m. (Use $\\pi = 3.14$.)", "parts": [{"stem": "Find the silo's total volume (cylinder plus cone).", "numericAnswer": "7222", "unit": "m^3", "hints": [], "solutionSteps": ["Cylinder's volume $= \\pi r^2 h = 3.14 \\times 10^2 \\times 15 = 4710\\ \\text{m}^3$", "Cone's volume $= \\frac{1}{3}\\pi r^2 h = \\frac{1}{3} \\times 3.14 \\times 10^2 \\times 24 = 2512\\ \\text{m}^3$", "Total $= 4710 + 2512 = 7222\\ \\text{m}^3$"], "marks": 2, "type": "numeric", "concept_ids": ["c9.sav.cylinder", "c9.sav.cone", "c9.sav.cuboid_cube", "c9.sav.pyramid", "c9.sav.sphere_hemisphere", "c9.sav.scaling", "c9.sav.units"]}, {"stem": "Find the silo's total outer surface area to be painted (the cylinder's curved surface, the cone's curved surface, and the base \u2014 the join between cylinder and cone is internal and excluded).", "numericAnswer": "2072.4", "unit": "m^2", "hints": [], "solutionSteps": ["Cone's slant height $l = \\sqrt{10^2+24^2} = \\sqrt{676} = 26\\ \\text{m}$", "Cylinder's curved surface $= 2\\pi rh = 2 \\times 3.14 \\times 10 \\times 15 = 942\\ \\text{m}^2$", "Cone's curved surface $= \\pi r l = 3.14 \\times 10 \\times 26 = 816.4\\ \\text{m}^2$", "Base $= \\pi r^2 = 3.14 \\times 100 = 314\\ \\text{m}^2$", "Total $= 942 + 816.4 + 314 = 2072.4\\ \\text{m}^2$"], "marks": 2, "type": "numeric", "concept_ids": ["c9.sav.cylinder", "c9.sav.cone", "c9.sav.cuboid_cube", "c9.sav.pyramid", "c9.sav.sphere_hemisphere", "c9.sav.scaling", "c9.sav.units"]}], "hints": [], "solutionSteps": []}$$::jsonb, 'live', 1);
